<?php require_once '../includes/auth.php';require_admin();verify_csrf();$id=(int)($_POST['id']??0);$st=$_POST['status']??'pending';if(!in_array($st,['pending','active','completed','archived'],true))exit('Invalid status');$s=mysqli_prepare($conn,"UPDATE records SET status=? WHERE id=?");mysqli_stmt_bind_param($s,'si',$st,$id);mysqli_stmt_execute($s);log_activity('status_changed','records','Changed record status to '.$st,$id);flash('success','Record status updated.');redirect('view.php?id='.$id);
